public class ConsumerRunner {interface Task{String run();}static void check(String name,boolean fail,Task task){ConsumerEffects.calls=0;ConsumerEffects.fail=fail;try{System.out.println(name+"="+task.run()+":"+ConsumerEffects.calls);}catch(RuntimeException e){System.out.println(name+"="+e.getClass().getName()+":"+(e==ConsumerEffects.FAILURE)+":"+ConsumerEffects.calls);}}public static void main(String[]args){for(boolean fail:new boolean[]{false,true}){check("cast"+fail,fail,()->""+(NewConsumers.cast() instanceof ConsumerValue));check("array"+fail,fail,()->{ConsumerValue[]a=new ConsumerValue[1];NewConsumers.array(a,0);return ""+a[0].number;});check("null"+fail,fail,()->{NewConsumers.array(null,0);return "returned";});check("bounds"+fail,fail,()->{NewConsumers.array(new ConsumerValue[0],0);return "returned";});check("type"+fail,fail,()->""+NewConsumers.type());check("field"+fail,fail,()->""+NewConsumers.field());check("call"+fail,fail,()->""+NewConsumers.call());}}}
